const rpc = $input.first().json;

if (rpc.error) {
  return [{ json: {
    success: false,
    error_type: rpc.error === 'clinic_not_found' ? 'clinic_not_found' : 'database_failure',
    message: 'Sorry, I could not look up the clinic location right now. Please try again shortly.'
  } }];
}

const hasAddress = Boolean(rpc.address_text && String(rpc.address_text).trim());

if (!hasAddress) {
  return [{ json: {
    success: true,
    configured: false,
    clinic_name: rpc.clinic_name,
    message: 'Location is not configured for this clinic yet. Ask the patient to contact the clinic directly for directions.'
  } }];
}

return [{ json: {
  success: true,
  configured: true,
  clinic_name: rpc.clinic_name,
  address_text: rpc.address_text,
  maps_url: rpc.maps_url || null,
  landmark_note: rpc.landmark_note || null,
  message: [
    rpc.clinic_name,
    rpc.address_text,
    rpc.landmark_note ? ('Landmark: ' + rpc.landmark_note) : null,
    rpc.maps_url ? ('Maps: ' + rpc.maps_url) : null
  ].filter(Boolean).join('\n')
} }];
